    for M in range(2, 11):
        for x1 in range(2, 501):
            x_list = [1, x1]
            current_sum_val = Fraction(1, x1)

            def dfs(idx, current_sum_val, current_x_list):
                if idx == M - 1:
                    R = Fraction(15, 16) - current_sum_val
                    if R > 0:
                        x_M_val = current_x_list[-1] / R
                        if x_M_val.denominator == 1:
                            x_M = x_M_val.numerator
                            x_prev = current_x_list[-2]
                            x_curr = current_x_list[-1]
                            L_M_minus_1 = 1 + (x_curr**3 - x_curr**2) / x_prev
                            if x_M >= L_M_minus_1:
                                solutions.append((M, current_x_list + [x_M]))
                    return

                x_curr = current_x_list[-1]
                x_prev = current_x_list[-2]
                L = 1 + (x_curr**3 - x_curr**2) / x_prev
                R = Fraction(15, 16) - current_sum_val
                if R <= 0:
                    return

                x_next_min = max(L, (x_curr / R).numerator // (x_curr / R).denominator + 1)

                for x_next in range(int(x_next_min), int(x_next_min + 200)):
